Item.Value:
SELECT M.ReadAuth, M.WriteAuth, U.Grade From DP_CMN_MenuAuth AS M WITH(NOLOCK) LEFT OUTER JOIN DP_CMN_UserInfo AS U WITH(NOLOCK) 
     ON M.CompanyID = U.CompanyID AND M.CommunityID = U.CommunityID 
     WHERE M.CompanyID = {0} AND M.CommunityID ={1} AND M.MenuID = {2} AND U.UserID = {3}

SELECT Count(*) as Cnt FROM DP_CMN_BOA as CB WITH(NOLOCK) INNER JOIN DP_CMN_MenuAuth as CM WITH(NOLOCK) 
		  ON CB.CompanyID = CM.CompanyID AND CB.CommunityID = CM.CommunityID AND CB.MenuID = CM.MenuID  
		WHERE CB.CompanyID = {0} AND CB.CommunityID = {1} 
		AND CB.BoardID not in (SELECT BoardID FROM DP_CMN_BoaView WITH(NOLOCK) WHERE CompanyID = CB.CompanyID AND CommunityID = CB.CommunityID AND MenuID = CB.MenuID)
		AND CM.ReadAuth >= {2}
